<script setup lang="ts">
import {onMounted,ref} from 'vue';import {useSkills} from '../stores/skills';import {displayTime} from '../domain/todos';
import Icon from './Icon.vue';import SkButton from './ui/SkButton.vue';import SkInput from './ui/SkInput.vue';import SkField from './ui/SkField.vue';
const skills=useSkills(),confirm=ref<HTMLDialogElement>();
async function scan(){try{await skills.scan();}catch{}}
async function restore(){try{await skills.restore();confirm.value?.close();}catch{confirm.value?.close();}}
onMounted(()=>{if(!skills.catalog&&!skills.loading)void scan();});
</script>
<template><section class="skills-page"><div class="skills-heading"><div><h2>Skills</h2><p>放入完整技能目录后重新扫描，新任务才会采用。</p></div><SkButton kind="entry" :disabled="skills.restoring" :loading="skills.loading" @click="scan"><Icon name="refresh"/>重新扫描</SkButton></div><SkField label="技能目录"><SkInput :model-value="skills.catalog?.root||''" readonly placeholder="正在读取工作目录"><template #suffix><button class="icon-button" type="button" title="打开技能目录" aria-label="打开技能目录" :disabled="!skills.catalog" @click="skills.openDirectory"><Icon name="folderOpen"/></button></template></SkInput></SkField><p class="skills-meta muted" v-if="skills.catalog">可用 {{skills.catalog.skills.length}} / {{skills.catalog.packages.length}} · 上次扫描 {{displayTime(skills.catalog.scannedAtMs)}}</p><p v-if="skills.error" class="form-error" role="alert">{{skills.error}} 请核对后重新扫描。</p><p v-if="skills.notice" class="skills-notice" role="status">{{skills.notice}}</p><p v-if="skills.loading&&!skills.catalog" role="status" class="muted">正在安装缺失的内置包并扫描…</p><div v-if="skills.catalog" class="skills-layout"><nav class="skills-list" aria-label="技能包"><button v-for="item in skills.catalog.packages" :key="item.relativePath" :disabled="skills.restoring||skills.loading" :class="{active:skills.selected===item.relativePath}" :aria-pressed="skills.selected===item.relativePath" @click="skills.selected=item.relativePath"><span>{{item.name||item.relativePath}}</span><small>{{item.diagnostics.length?'不可用':item.installationConflict?'保留同名用户包':item.modified?'本地已修改':item.builtinId?'内置':'自定义'}}</small></button></nav><section v-if="skills.current" class="skills-detail" aria-label="技能详情"><header><div><h3>{{skills.current.name||skills.current.relativePath}}</h3><small class="muted">{{skills.current.relativePath}}</small></div><SkButton v-if="skills.current.builtinId" :disabled="!skills.ready||!skills.current.hash||skills.loading||skills.restoring" @click="confirm?.showModal()">恢复内置版本</SkButton></header><p>{{skills.current.description||'这个目录暂未形成可用的技能入口。'}}</p><p class="muted">{{skills.current.fileCount||0}} 个文件 · {{((skills.current.bytes||0)/1024).toFixed(1)}} KB</p><p v-if="skills.current.installationConflict" class="skills-warning">已有同名目录，保留用户版本；内置包没有覆盖它。</p><p v-else-if="skills.current.modified" class="skills-warning">本地内容与内置版本不同，重扫和升级都会保留你的修改。</p><ul v-if="skills.current.diagnostics.length" class="skills-diagnostics"><li v-for="(item,index) in skills.current.diagnostics" :key="index"><strong>{{item.message}}</strong><small>{{item.path}} · {{item.code}}</small></li></ul><p v-else class="skills-available"><Icon name="check"/>已纳入索引，班班会按需读取正文和支持文件。</p><details v-if="skills.current.builtinFiles?.length" class="skills-files"><summary>内置文件清单（{{skills.current.builtinFiles.length}}）</summary><ul><li v-for="file in skills.current.builtinFiles" :key="file">{{file}}</li></ul></details></section><p v-else class="muted">目录中还没有技能。放入包含 SKILL.md 的完整文件夹后重新扫描。</p></div><p class="skills-boundary muted">任务使用启动时的技能副本。Read／Bash 使用当前用户权限，工作目录并非沙箱。</p><dialog ref="confirm" class="dialog confirm-dialog" aria-labelledby="skill-restore-heading" @cancel.prevent="!skills.restoring&&confirm?.close()"><header class="dialog-header"><h2 id="skill-restore-heading">恢复 {{skills.current?.name||skills.current?.relativePath}}？</h2></header><div class="dialog-body"><p>将恢复 {{skills.current?.builtinFiles?.length||0}} 个内置文件。当前目录会先整体备份到工作目录的 backups，再替换为随包版本。</p><p class="muted">只处理这个技能包；后续编辑导致内容变化时会停止，请重新扫描后确认。</p></div><footer class="dialog-footer"><SkButton :disabled="skills.restoring" @click="confirm?.close()">取消</SkButton><SkButton kind="commit" :loading="skills.restoring" @click="restore">备份并恢复</SkButton></footer></dialog></section></template>
